import java.security.*; import java.util.Base64; import java.io.*; public class ExportKeys { public static void main(String[] args) throws Exception { KeyPairGenerator kpg = KeyPairGenerator.getInstance("RSA"); kpg.initialize(2048); KeyPair kp = kpg.generateKeyPair(); byte[] privBytes = kp.getPrivate().getEncoded(); String privB64 = Base64.getMimeEncoder(64, new byte[]{10}).encodeToString(privBytes); String privPem = "-----BEGIN PRIVATE KEY-----\n" + privB64 + "\n-----END PRIVATE KEY-----\n"; byte[] pubBytes = kp.getPublic().getEncoded(); String pubB64 = Base64.getMimeEncoder(64, new byte[]{10}).encodeToString(pubBytes); String pubPem = "-----BEGIN PUBLIC KEY-----\n" + pubB64 + "\n-----END PUBLIC KEY-----\n"; PrintWriter pw1 = new PrintWriter(new FileWriter(args[0])); pw1.print(privPem); pw1.close(); PrintWriter pw2 = new PrintWriter(new FileWriter(args[1])); pw2.print(pubPem); pw2.close(); System.out.println("done"); } }